"use server";

import { revalidatePath } from "next/cache";
import { redirect } from "next/navigation";
import { auth } from "@/auth";
import { prisma } from "@/lib/prisma";
import { initializeFeatures } from "./features";
import bcrypt from "bcryptjs";

export async function createTenant(formData: FormData) {
  const session = await auth();

  const isSuperAdmin = Boolean(
    session?.user && (session.user as { isSuperAdmin?: boolean }).isSuperAdmin,
  );
  if (!isSuperAdmin) {
    redirect("/");
  }

  const name = String(formData.get("name") ?? "").trim();
  const slug = String(formData.get("slug") ?? "")
    .trim()
    .toLowerCase();
  const planId = String(formData.get("planId") ?? "").trim();
  const adminEmail = String(formData.get("adminEmail") ?? "").trim().toLowerCase();
  const adminPassword = String(formData.get("adminPassword") ?? "").trim();
  const adminName = String(formData.get("adminName") ?? "").trim();

  if (!name || !slug || !planId) {
    return;
  }

  // Basic safety: ensure slug is unique
  const existing = await prisma.tenant.findUnique({ where: { slug } });
  if (existing) {
    return;
  }

  const tenant = await prisma.tenant.create({
    data: {
      name,
      slug,
      status: "ACTIVE",
    },
  });

  await prisma.subscription.create({
    data: {
      tenantId: tenant.id,
      planId,
      status: "ACTIVE",
      currentPeriodStart: new Date(),
      currentPeriodEnd: new Date(Date.now() + 30 * 24 * 60 * 60 * 1000),
    },
  });

  // Initialize default features for the tenant
  await initializeFeatures(tenant.id);

  // Create admin user for the tenant if email + password provided
  if (adminEmail && adminPassword) {
    let adminUser = await prisma.user.findUnique({
      where: { email: adminEmail },
    });

    if (!adminUser) {
      const hashedPassword = await bcrypt.hash(adminPassword, 10);
      adminUser = await prisma.user.create({
        data: {
          email: adminEmail,
          name: adminName || adminEmail.split("@")[0],
          password: hashedPassword,
        },
      });
    }

    // Add as TENANT_ADMIN
    await prisma.tenantUser.upsert({
      where: {
        tenantId_userId: {
          tenantId: tenant.id,
          userId: adminUser.id,
        },
      },
      update: { role: "TENANT_ADMIN" },
      create: {
        tenantId: tenant.id,
        userId: adminUser.id,
        role: "TENANT_ADMIN",
      },
    });
  }

  revalidatePath("/admin");
  redirect("/admin");
}
